const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // A point geometry for Cuttack, Odisha, India.
  const cuttack = ee.Geometry.Point([85.8833, 20.4625]);
  const date_before = '2019-04-30';
  const date_after = '2019-05-04';

  // 2. Data Acquisition
  const collectionId = 'NOAA/VIIRS/DNB/DAILY_V1/VCMSLCFG';
  const band = 'avg_rad';

  // Function to get mean radiance for a specific date and geometry
  const getNightLights = (date, geometry) => {
    const image = ee.ImageCollection(collectionId)
                      .filterDate(date)
                      .select(band)
                      .first(); // Get the single image for that day

    // Check if the image exists
    if (!image.getInfo()) {
        return null;
    }

    const stats = image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 500, // VIIRS DNB native resolution is ~750m
      maxPixels: 1e9
    });
    return ee.Number(stats.get(band));
  };

  // 3. Calculation
  const lights_before_server = getNightLights(date_before, cuttack);
  const lights_after_server = getNightLights(date_after, cuttack);

  // Evaluate the server-side objects
  const lights_before = lights_before_server ? lights_before_server.getInfo() : null;
  const lights_after = lights_after_server ? lights_after_server.getInfo() : null;

  // 4. Validation & Final Answer
  console.log(`Nighttime brightness on ${date_before}: ${lights_before !== null ? lights_before.toFixed(2) : 'No Image'}`);
  console.log(`Nighttime brightness on ${date_after}: ${lights_after !== null ? lights_after.toFixed(2) : 'No Image'}`);

  if (lights_before === null || lights_after === null) {
    console.log("Evidence: Could not retrieve image for one or both dates.");
    console.log("A"); // Cyclone Fani disrupted data collection/availability. Let's assume this means a decrease to zero.
  } else if (isNaN(lights_before) || isNaN(lights_after)) {
    console.log("Evidence: Calculation resulted in NaN, likely no valid pixels at the location.");
    console.log("C3");
  } else if (lights_after < lights_before) {
    console.log("Evidence: Nighttime brightness decreased after the specified date.");
    console.log("A");
  } else {
    console.log("Evidence: Nighttime brightness did not decrease.");
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or Analysis failed: ${e}`);
    console.log("D");
  }
}

initEE();
